UPDATE t_comment_outbox
SET status = 'SENT', sent_time = #{sentTime}, lease_owner = NULL, lease_until = NULL,
    last_error = NULL, updated_time = #{sentTime}
WHERE id = #{id} AND status = 'SENDING' AND lease_owner = #{owner} AND lease_version = #{leaseVersion}

UPDATE t_comment_outbox
SET status = 'PENDING', next_attempt_at = #{nextAttemptAt}, last_error = #{lastError},
    lease_owner = NULL, lease_until = NULL, updated_time = #{updatedTime}
WHERE id = #{id} AND status = 'SENDING' AND lease_owner = #{owner} AND lease_version = #{leaseVersion}
